const $=s=>document.querySelector(s), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base='https://api.jolpi.ca/ergast/f1';let generation=0,target=null,races=[],timer=null,resultRequest=0;
const when=r=>r.time?new Date(`${r.date}T${r.time}`):null;
const dateLabel=r=>when(r)?when(r).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}):`${r.date} · 发车时间待确认`;
async function request(path){const response=await fetch(`${base}/${path}${path.includes('?')?'&':'?'}limit=100`,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`HTTP ${response.status}`);const data=await response.json();if(!data.MRData)throw Error('数据格式异常');return data.MRData;}
function table(headers,rows){return rows.length?`<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p class="empty">该赛季暂无数据。</p>';}
function driverRows(items){return items.map(x=>[esc(x.position),`${esc(x.Driver.givenName)} ${esc(x.Driver.familyName)}<small>${esc(x.Constructors.map(c=>c.name).join(' / '))}</small>`,esc(x.wins),esc(x.points)]);}
function teamRows(items){return items.map(x=>[esc(x.position),esc(x.Constructor.name),esc(x.wins),esc(x.points)]);}
function cards(items){return items.length?items.map(r=>`<div class="race-card"><small>ROUND ${esc(r.round)} / ${when(r)&&when(r)<new Date()?'已到赛期':'赛程'}</small><h3>${esc(r.raceName)}</h3><p>${esc(r.Circuit.circuitName)}</p><p>${esc(dateLabel(r))}</p></div>`).join(''):'<p class="empty">暂无后续赛程</p>';}
function tick(){if(!target)return;const diff=target-Date.now();if(diff<=0){$('#countdown').textContent='已到发车时间';return;}let n=Math.floor(diff/1000);const d=Math.floor(n/86400);n%=86400;const h=Math.floor(n/3600);n%=3600;$('#countdown').textContent=[d,h,Math.floor(n/60),n%60].map(v=>String(v).padStart(2,'0')).join(' : ');}
async function results(){const id=++resultRequest,round=$('#result-round').value,year=$('#season').value;$('#result-table').innerHTML='';if(!round){$('#result-status').textContent='该赛季暂无比赛';return;}$('#result-status').textContent='正在获取赛果…';try{const data=await request(`${year}/${round}/results.json`);if(id!==resultRequest)return;const race=data.RaceTable.Races[0];$('#result-status').textContent=race?`${race.raceName} · 正赛结果`:'尚未发布正赛结果';$('#result-table').innerHTML=table(['名次','车手 / 车队','时间 / 状态','积分'],(race?.Results||[]).map(x=>[esc(x.position),`${esc(x.Driver.givenName)} ${esc(x.Driver.familyName)}<small>${esc(x.Constructor.name)}</small>`,esc(x.Time?.time||x.status),esc(x.points)]));}catch(e){if(id===resultRequest)$('#result-status').textContent='赛果暂时无法获取，请稍后重试。';}}
async function load(){const id=++generation;++resultRequest;target=null;clearInterval(timer);$('#refresh').disabled=true;$('#status').textContent='正在请求 Jolpica 赛事数据…';$('#countdown').textContent='— : — : — : —';$('#race-name').textContent='正在加载赛程';$('#circuit').textContent='';$('#race-date').textContent='';for(const s of ['driver-top','team-top','driver-full','team-full','calendar-list','upcoming','result-table'])$('#'+s).innerHTML='<p class="loading">正在加载…</p>';$('#result-round').innerHTML='';$('#progress').style.width='0%';$('#progress-text').textContent='等待赛程';const year=$('#season').value;const responses=await Promise.allSettled([request(`${year}.json`),request(`${year}/driverStandings.json`),request(`${year}/constructorStandings.json`)]);if(id!==generation)return;let failed=0;const [cal,drv,team]=responses;
if(cal.status==='fulfilled'){races=cal.value.RaceTable.Races;const now=new Date();const next=races.find(r=>when(r)?when(r)>now:r.date>=now.toISOString().slice(0,10));if(next){$('#race-name').textContent=next.raceName;$('#circuit').textContent=`${next.Circuit.circuitName} · ${next.Circuit.Location.locality}, ${next.Circuit.Location.country}`;$('#race-date').textContent=dateLabel(next);target=when(next)?.getTime()||null;$('#countdown').textContent=target?'—':'发车时间待确认';tick();timer=setInterval(tick,1000);}else{$('#race-name').textContent=races.length?'本赛季赛程已结束':'赛程尚未发布';$('#countdown').textContent='—';}$('#calendar-list').innerHTML=cards(races);const done=races.filter(r=>when(r)?when(r)<now:r.date<now.toISOString().slice(0,10)).length;$('#progress-text').textContent=`${done} / ${races.length} 站已到赛期`;$('#progress').style.width=`${races.length?done/races.length*100:0}%`;$('#upcoming').innerHTML=cards(races.filter(r=>when(r)?when(r)>now:r.date>=now.toISOString().slice(0,10)).slice(0,3));$('#result-round').innerHTML=races.map(r=>`<option value="${esc(r.round)}">R${esc(r.round)} · ${esc(r.raceName)}</option>`).join('');if(done)$('#result-round').value=races[done-1].round;results();}else{failed++;$('#race-name').textContent='赛程暂时无法获取';for(const s of ['calendar-list','upcoming'])$('#'+s).textContent='连接失败，请点击刷新重试';$('#result-status').textContent='加载赛程后可选择比赛';$('#result-table').innerHTML='';}
for(const [response,kind,convert] of [[drv,'driver',driverRows],[team,'team',teamRows]]){if(response.status==='fulfilled'){const list=response.value.StandingsTable.StandingsLists[0];const items=list?.[kind==='driver'?'DriverStandings':'ConstructorStandings']||[];const headers=['名次',kind==='driver'?'车手 / 车队':'车队','胜场','积分'];$('#'+kind+'-top').innerHTML=table(headers,convert(items.slice(0,5)));$('#'+kind+'-full').innerHTML=table(headers,convert(items));}else{failed++;$('#'+kind+'-top').textContent='数据暂时不可用，请刷新重试';$('#'+kind+'-full').textContent='数据暂时不可用，请刷新重试';}}
$('#status').textContent=failed?`${failed} 类数据获取失败 · 可点击刷新重试 · 不显示模拟积分`:`已获取数据 · ${new Date().toLocaleString('zh-CN')} · 每 5 分钟自动刷新（页面打开期间）`;$('#refresh').disabled=false;}
for(let y=new Date().getFullYear();y>=2020;y--)$('#season').add(new Option(`${y} 赛季`,y));$('#season').onchange=load;$('#refresh').onclick=load;$('#result-round').onchange=results;document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==b.dataset.view);});load();setInterval(()=>{if(!document.hidden&&!$('#refresh').disabled)load();},300000);
